package com.aetherforge.api;
import com.aetherforge.repo.UserRepository;import com.aetherforge.security.TokenService;import jakarta.validation.constraints.*;import org.springframework.http.HttpHeaders;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { record Login(@Email String email,@NotBlank String password){};private final UserRepository users;private final PasswordEncoder enc;private final TokenService tokens;public AuthController(UserRepository u,PasswordEncoder e,TokenService t){users=u;enc=e;tokens=t;} @PostMapping("/login") Map<String,Object> login(@RequestBody Login in){var u=users.byEmail(in.email());if(!enc.matches(in.password(),String.valueOf(u.get("password_hash"))))throw new IllegalArgumentException("Invalid credentials");String t=tokens.issue(String.valueOf(u.get("email")),String.valueOf(u.get("role")));return Map.of("token",t,"user",Map.of("email",u.get("email"),"name",u.get("full_name"),"role",u.get("role")));} @PostMapping("/logout") Map<String,Object> logout(@RequestHeader(HttpHeaders.AUTHORIZATION) String h){if(h!=null&&h.startsWith("Bearer "))tokens.revoke(h.substring(7));return Map.of("ok",true);} @GetMapping("/me") Map<String,Object> me(){var a=SecurityContextHolder.getContext().getAuthentication();return Map.of("email",a.getName(),"role",a.getAuthorities().iterator().next().getAuthority().replace("ROLE_",""));} }
